"""Offline synthetic QUIC v1 trace auditor.

Reads one JSON document from stdin and writes one JSON document to stdout.
Invalid input produces {"error":"INVALID_INPUT"}.
"""
import sys
import json
import re
import bisect

MAX_OFF = 4611686018427387903  # 2**62 - 1
MAX_T = 1000000000000
MAX_IDLE = 1000000000
MAX_REQUEST = 16 * 1024 * 1024
MAX_FRAME_DATA = 2 * 1024 * 1024
MAX_RANGE_PAIRS = 32


class InvalidInput(Exception):
    pass


class ProtoError(Exception):
    __slots__ = ("code", "frame")

    def __init__(self, code, frame):
        self.code = code
        self.frame = frame


def _reject_constant(_s):
    raise InvalidInput()


def _reject_float(_s):
    raise InvalidInput()


def _no_duplicate_pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise InvalidInput()
        d[k] = v
    return d


_HEX_RE = re.compile(r"[0-9a-f]*\Z")


def _is_int(v):
    return type(v) is int


def _is_bool(v):
    return type(v) is bool


def _need_dict(v, keys):
    if type(v) is not dict:
        raise InvalidInput()
    if len(v) != len(keys):
        raise InvalidInput()
    for k in keys:
        if k not in v:
            raise InvalidInput()
    return v


def _hex_len(s):
    if type(s) is not str:
        raise InvalidInput()
    n = len(s)
    if n > 4096 or (n & 1):
        raise InvalidInput()
    if _HEX_RE.fullmatch(s) is None:
        raise InvalidInput()
    return n // 2


def _int_domain(v, lo, hi):
    if not _is_int(v) or v < lo or v > hi:
        raise InvalidInput()
    return v


def _validate_ranges(v, config):
    """Structural validation.  Returns decoded pairs (list of tuples)."""
    if type(v) is not list:
        raise InvalidInput()
    if len(v) > MAX_RANGE_PAIRS:
        raise InvalidInput()
    out = []
    prev_low = None
    prev_high = None
    for pair in v:
        if type(pair) is not list or len(pair) != 2:
            raise InvalidInput()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise InvalidInput()
        if lo < 0 or lo > MAX_OFF or hi < 0 or hi > MAX_OFF:
            raise InvalidInput()
        if config:
            if lo > hi:
                raise InvalidInput()
            if prev_low is not None:
                # must ascend by low, be disjoint and nonadjacent
                if lo <= prev_high + 1:
                    raise InvalidInput()
            prev_low = lo
            prev_high = hi
        out.append((lo, hi))
    return out


FRAME_KEYS = {
    "PADDING": frozenset(("type",)),
    "PING": frozenset(("type",)),
    "ACK": frozenset(("type", "ranges")),
    "CRYPTO": frozenset(("type", "offset", "data_hex")),
    "STREAM": frozenset(("type", "id", "offset", "data_hex", "fin")),
    "RESET_STREAM": frozenset(("type", "id", "final_size")),
    "STOP_SENDING": frozenset(("type", "id")),
    "CLOSE": frozenset(("type", "app", "code")),
    "HANDSHAKE_DONE": frozenset(("type",)),
    "UNKNOWN": frozenset(("type",)),
}


def _validate_frame(fr):
    if type(fr) is not dict:
        raise InvalidInput()
    typ = fr.get("type")
    if type(typ) is not str or typ not in FRAME_KEYS:
        raise InvalidInput()
    keys = FRAME_KEYS[typ]
    if len(fr) != len(keys):
        raise InvalidInput()
    for k in keys:
        if k not in fr:
            raise InvalidInput()
    if typ == "PADDING" or typ == "PING" or typ == "HANDSHAKE_DONE" or typ == "UNKNOWN":
        return 0
    if typ == "ACK":
        _validate_ranges(fr["ranges"], False)
        return 0
    if typ == "CRYPTO":
        _int_domain(fr["offset"], 0, MAX_OFF)
        return _hex_len(fr["data_hex"])
    if typ == "STREAM":
        _int_domain(fr["id"], 0, MAX_OFF)
        _int_domain(fr["offset"], 0, MAX_OFF)
        if not _is_bool(fr["fin"]):
            raise InvalidInput()
        return _hex_len(fr["data_hex"])
    if typ == "RESET_STREAM":
        _int_domain(fr["id"], 0, MAX_OFF)
        _int_domain(fr["final_size"], 0, MAX_OFF)
        return 0
    if typ == "STOP_SENDING":
        _int_domain(fr["id"], 0, MAX_OFF)
        return 0
    if typ == "CLOSE":
        if not _is_bool(fr["app"]):
            raise InvalidInput()
        _int_domain(fr["code"], 0, MAX_OFF)
        return 0
    raise InvalidInput()


def _validate_config(cfg):
    _need_dict(cfg, ("early", "overlap", "buffer_packets", "idle_ms",
                     "max_streams_bidi", "max_streams_uni", "max_stream_data",
                     "max_data", "crypto_limit", "sent"))
    if not _is_bool(cfg["early"]):
        raise InvalidInput()
    if cfg["overlap"] not in ("reject", "first"):
        raise InvalidInput()
    if type(cfg["overlap"]) is not str:
        raise InvalidInput()
    _int_domain(cfg["buffer_packets"], 0, 1024)
    _int_domain(cfg["idle_ms"], 0, MAX_IDLE)
    _int_domain(cfg["max_streams_bidi"], 0, 1024)
    _int_domain(cfg["max_streams_uni"], 0, 1024)
    _int_domain(cfg["max_stream_data"], 0, 65536)
    _int_domain(cfg["max_data"], 0, MAX_OFF)
    _int_domain(cfg["crypto_limit"], 0, 65536)
    sent = _need_dict(cfg["sent"], ("I", "H", "A"))
    for lvl in ("I", "H", "A"):
        _validate_ranges(sent[lvl], True)


EVENT_KEYS = {
    "key": frozenset(("t", "op", "level", "action")),
    "tick": frozenset(("t", "op")),
    "datagram": frozenset(("t", "op", "bytes", "packets")),
}

LEVELS = ("I", "H", "Z", "A")
_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")


def _validate_root(obj):
    _need_dict(obj, ("version", "traces"))
    if not _is_int(obj["version"]) or obj["version"] != 1:
        raise InvalidInput()
    traces = obj["traces"]
    if type(traces) is not list:
        raise InvalidInput()
    if len(traces) > 32:
        raise InvalidInput()
    seen_ids = set()
    total_events = 0
    total_packets = 0
    total_frames = 0
    total_data = 0
    for tr in traces:
        _need_dict(tr, ("id", "config", "events"))
        tid = tr["id"]
        if type(tid) is not str or _ID_RE.fullmatch(tid) is None:
            raise InvalidInput()
        if tid in seen_ids:
            raise InvalidInput()
        seen_ids.add(tid)
        _validate_config(tr["config"])
        events = tr["events"]
        if type(events) is not list:
            raise InvalidInput()
        total_events += len(events)
        if total_events > 20000:
            raise InvalidInput()
        prev_t = -1
        for ev in events:
            if type(ev) is not dict:
                raise InvalidInput()
            op = ev.get("op")
            if type(op) is not str or op not in EVENT_KEYS:
                raise InvalidInput()
            keys = EVENT_KEYS[op]
            if len(ev) != len(keys):
                raise InvalidInput()
            for k in keys:
                if k not in ev:
                    raise InvalidInput()
            t = _int_domain(ev["t"], 0, MAX_T)
            if t < prev_t:
                raise InvalidInput()
            prev_t = t
            if op == "key":
                if ev["level"] not in LEVELS:
                    raise InvalidInput()
                if type(ev["level"]) is not str:
                    raise InvalidInput()
                if ev["action"] not in ("install", "discard"):
                    raise InvalidInput()
                if type(ev["action"]) is not str:
                    raise InvalidInput()
            elif op == "tick":
                pass
            else:
                _int_domain(ev["bytes"], 0, 65535)
                packets = ev["packets"]
                if type(packets) is not list:
                    raise InvalidInput()
                if len(packets) < 1 or len(packets) > 16:
                    raise InvalidInput()
                total_packets += len(packets)
                if total_packets > 20000:
                    raise InvalidInput()
                for pkt in packets:
                    _need_dict(pkt, ("level", "pn", "auth", "frames"))
                    if pkt["level"] not in LEVELS:
                        raise InvalidInput()
                    if type(pkt["level"]) is not str:
                        raise InvalidInput()
                    _int_domain(pkt["pn"], 0, MAX_OFF)
                    if not _is_bool(pkt["auth"]):
                        raise InvalidInput()
                    frames = pkt["frames"]
                    if type(frames) is not list:
                        raise InvalidInput()
                    if len(frames) > 64:
                        raise InvalidInput()
                    total_frames += len(frames)
                    if total_frames > 60000:
                        raise InvalidInput()
                    for fr in frames:
                        total_data += _validate_frame(fr)
                        if total_data > MAX_FRAME_DATA:
                            raise InvalidInput()
    return obj


def _parse(raw):
    if len(raw) > MAX_REQUEST:
        raise InvalidInput()
    try:
        text = raw.decode("utf-8")
    except Exception:
        raise InvalidInput()
    try:
        obj = json.loads(
            text,
            object_pairs_hook=_no_duplicate_pairs,
            parse_constant=_reject_constant,
            parse_float=_reject_float,
        )
    except InvalidInput:
        raise
    except Exception:
        raise InvalidInput()
    return obj


# ---------------------------------------------------------------------------
# Replay


_MISSING = object()


class TraceRunner:
    __slots__ = (
        "cfg", "early", "overlap", "buffer_packets", "idle_ms",
        "max_streams_bidi", "max_streams_uni", "max_stream_data",
        "max_data", "crypto_limit", "sent", "sent_lows",
        "keys", "state", "code", "at_ms", "source", "peer_code",
        "last_activity", "pending", "pnsets", "streams", "tot", "crypto",
        "results",
    )

    def __init__(self, trace):
        cfg = trace["config"]
        self.cfg = cfg
        self.early = cfg["early"]
        self.overlap = cfg["overlap"]
        self.buffer_packets = cfg["buffer_packets"]
        self.idle_ms = cfg["idle_ms"]
        self.max_streams_bidi = cfg["max_streams_bidi"]
        self.max_streams_uni = cfg["max_streams_uni"]
        self.max_stream_data = cfg["max_stream_data"]
        self.max_data = cfg["max_data"]
        self.crypto_limit = cfg["crypto_limit"]
        self.sent = cfg["sent"]
        self.sent_lows = {
            lvl: [pair[0] for pair in cfg["sent"][lvl]] for lvl in ("I", "H", "A")
        }

        self.keys = {
            "I": "live",
            "H": "absent",
            "Z": "live" if self.early else "absent",
            "A": "absent",
        }
        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0
        self.pending = []
        self.pnsets = {"I": set(), "H": set(), "A": set()}
        self.streams = {}
        self.tot = {"v": 0}
        self.crypto = {
            "I": {"highest": 0, "bytes": {}, "contiguous": 0},
            "H": {"highest": 0, "bytes": {}, "contiguous": 0},
            "A": {"highest": 0, "bytes": {}, "contiguous": 0},
        }
        self.results = []

    # -- bookkeeping -----------------------------------------------------

    def add_result(self, e, p, status, reason, at, frame):
        self.results.append({
            "event": e,
            "packet": p,
            "status": status,
            "reason": reason,
            "at_ms": at,
            "frame": frame,
        })

    def terminate(self, state, code, at, e, p, f, peer=None):
        self.state = state
        self.code = code
        self.at_ms = at
        self.source = {"event": e, "packet": p, "frame": f}
        self.peer_code = peer
        # Any already pending packets are dropped at termination time.
        if self.pending:
            for job in self.pending:
                self.add_result(job["e"], job["p"], "dropped",
                                "CONNECTION_CLOSED", at, None)
            self.pending = []

    def fail_packet(self, e, p, at, frame, code):
        self.terminate("closed", code, at, e, p, frame)
        self.add_result(e, p, "error", code, at, frame)

    # -- event loop ------------------------------------------------------

    def run(self, events):
        for e, ev in enumerate(events):
            t = ev["t"]
            if (self.state == "open" and self.idle_ms != 0 and
                    t >= self.last_activity + self.idle_ms):
                self.terminate("idle", "IDLE_TIMEOUT",
                               self.last_activity + self.idle_ms,
                               e, None, None)
            op = ev["op"]
            if op == "datagram":
                self.handle_datagram(e, ev, t)
            elif op == "key":
                if self.state == "open":
                    self.handle_key(e, ev, t)
            # tick: nothing to do (idle was checked above)

        # EOF: no extra time passes.  Still-pending packets are buffered.
        if self.pending:
            for job in self.pending:
                self.add_result(job["e"], job["p"], "buffered", "NO_KEYS",
                                job["arrival"], None)
            self.pending = []
        return self.build_result()

    def handle_key(self, e, ev, t):
        lvl = ev["level"]
        token = ev["action"]
        if token == "discard":
            self.keys[lvl] = "discarded"
            if self.pending:
                remaining = []
                for job in self.pending:
                    if job["level"] == lvl:
                        self.add_result(job["e"], job["p"], "dropped",
                                        "KEYS_DISCARDED", t, None)
                    else:
                        remaining.append(job)
                self.pending = remaining
        else:  # install
            if self.keys[lvl] == "absent":
                self.keys[lvl] = "live"
                self.drain_level(lvl, t)
            # installing live/discarded is a no-op

    def drain_level(self, lvl, t):
        # Process matching pending packets in original arrival order.
        while self.state == "open":
            idx = -1
            for i, job in enumerate(self.pending):
                if job["level"] == lvl:
                    idx = i
                    break
            if idx < 0:
                break
            job = self.pending.pop(idx)
            self.process_packet(job["e"], job["p"], job["pkt"], t,
                                job["size"], drained=True)

    def handle_datagram(self, e, ev, t):
        packets = ev["packets"]
        if self.state != "open":
            for p in range(len(packets)):
                self.add_result(e, p, "dropped", "CONNECTION_CLOSED", t, None)
            return
        # Normalized short-header boundary policy: any non-final A packet
        # makes the whole datagram's packet layout invalid.
        for p in range(len(packets) - 1):
            if packets[p]["level"] == "A":
                for q in range(len(packets)):
                    self.add_result(e, q, "dropped", "LAYOUT", t, None)
                return
        size = ev["bytes"]
        for p, pkt in enumerate(packets):
            if self.state != "open":
                self.add_result(e, p, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            self.process_packet(e, p, pkt, t, size, drained=False)

    # -- packet processing ----------------------------------------------

    def process_packet(self, e, p, pkt, t, size, drained):
        lvl = pkt["level"]
        pn = pkt["pn"]
        auth = pkt["auth"]

        if not drained:
            if lvl == "I" and size < 1200:
                self.add_result(e, p, "dropped", "INITIAL_TOO_SMALL", t, None)
                return
            if lvl == "Z" and not self.early:
                self.add_result(e, p, "dropped", "EARLY_REJECTED", t, None)
                return

        kstate = self.keys[lvl]
        if kstate == "discarded":
            self.add_result(e, p, "dropped", "KEYS_DISCARDED", t, None)
            return
        if kstate == "absent":
            if len(self.pending) < self.buffer_packets:
                self.pending.append({
                    "e": e, "p": p, "arrival": t,
                    "pkt": pkt, "level": lvl, "size": size,
                })
            else:
                self.add_result(e, p, "dropped", "BUFFER_FULL", t, None)
            return

        if not auth:
            self.add_result(e, p, "dropped", "AUTH", t, None)
            return

        if lvl == "I":
            pnset = self.pnsets["I"]
        elif lvl == "H":
            pnset = self.pnsets["H"]
        else:
            pnset = self.pnsets["A"]  # Z and A share the Application PN space
        if pn in pnset:
            self.add_result(e, p, "duplicate", "DUPLICATE", t, None)
            return

        self.process_frames(e, p, t, pkt, pnset)

    # -- frame preflight and semantics ----------------------------------

    def process_frames(self, e, p, t, pkt, pnset):
        lvl = pkt["level"]
        frames = pkt["frames"]

        if not frames:
            self.fail_packet(e, p, t, None, "FRAME_ENCODING_ERROR")
            return

        # Preflight: entire array, in order.
        for fi, fr in enumerate(frames):
            typ = fr["type"]
            if typ == "UNKNOWN":
                self.fail_packet(e, p, t, fi, "FRAME_ENCODING_ERROR")
                return
            if not _frame_allowed(typ, lvl, fr):
                self.fail_packet(e, p, t, fi, "PROTOCOL_VIOLATION")
                return

        # Semantic processing is atomic for this packet.
        journal = []
        overlap = self.overlap
        max_stream_data = self.max_stream_data
        max_data = self.max_data
        crypto_limit = self.crypto_limit

        def set_attr(obj, name, val):
            journal.append(("a", obj, name, obj[name]))
            obj[name] = val

        def put_byte(d, off, val):
            journal.append(("b", d, off, d.get(off, _MISSING)))
            d[off] = val

        def create_stream(sid):
            ent = {
                "id": sid,
                "highest": 0,
                "final_size": None,
                "reset": False,
                "stopped": False,
                "bytes": {},
                "delivered": 0,
            }
            self.streams[sid] = ent
            journal.append(("c", sid))
            return ent

        def rollback():
            for op in reversed(journal):
                kind = op[0]
                if kind == "a":
                    op[1][op[2]] = op[3]
                elif kind == "b":
                    d, off, old = op[1], op[2], op[3]
                    if old is _MISSING:
                        del d[off]
                    else:
                        d[off] = old
                else:  # "c"
                    self.streams.pop(op[1], None)

        def store_bytes(bmap, offset, data, fi):
            for i, b in enumerate(data):
                off = offset + i
                old = bmap.get(off, _MISSING)
                if old is not _MISSING:
                    if old != b:
                        if overlap == "reject":
                            raise ProtoError("PROTOCOL_VIOLATION", fi)
                        # overlap == "first": keep the earlier byte
                else:
                    put_byte(bmap, off, b)

        def dir_count(sid, allow_uni):
            m = sid & 3
            if m == 0:
                lim = self.max_streams_bidi
            elif m == 2 and allow_uni:
                lim = self.max_streams_uni
            else:
                raise ProtoError("STREAM_STATE_ERROR", fi)
            if (sid >> 2) + 1 > lim:
                raise ProtoError("STREAM_LIMIT_ERROR", fi)

        fi = -1
        try:
            for fi, fr in enumerate(frames):
                typ = fr["type"]
                if typ == "PADDING" or typ == "PING":
                    continue

                if typ == "CLOSE":
                    # Commit prior effects and this packet, then terminate.
                    pnset.add(pkt["pn"])
                    self.last_activity = t
                    if fr["app"]:
                        code = "PEER_APPLICATION_CLOSE"
                    else:
                        code = "PEER_TRANSPORT_CLOSE"
                    self.terminate("closed", code, t, e, p, fi,
                                   peer=fr["code"])
                    self.add_result(e, p, "accepted", "OK", t, None)
                    return

                if typ == "ACK":
                    ranges = fr["ranges"]
                    if not ranges:
                        raise ProtoError("FRAME_ENCODING_ERROR", fi)
                    prev_high = None
                    for lo, hi in ranges:
                        if lo > hi:
                            raise ProtoError("FRAME_ENCODING_ERROR", fi)
                        if prev_high is not None and lo <= prev_high + 1:
                            raise ProtoError("FRAME_ENCODING_ERROR", fi)
                        prev_high = hi
                    sent = self.sent[lvl]
                    lows = self.sent_lows[lvl]
                    for lo, hi in ranges:
                        idx = bisect.bisect_right(lows, lo) - 1
                        if idx < 0 or hi > sent[idx][1]:
                            raise ProtoError("PROTOCOL_VIOLATION", fi)
                    continue

                if typ == "CRYPTO":
                    data = bytes.fromhex(fr["data_hex"])
                    end = fr["offset"] + len(data)
                    if end > MAX_OFF:
                        raise ProtoError("FRAME_ENCODING_ERROR", fi)
                    if end > crypto_limit:
                        raise ProtoError("CRYPTO_BUFFER_EXCEEDED", fi)
                    st = self.crypto[lvl]
                    store_bytes(st["bytes"], fr["offset"], data, fi)
                    if end > st["highest"]:
                        set_attr(st, "highest", end)
                    bmap = st["bytes"]
                    d = st["contiguous"]
                    while d in bmap:
                        d += 1
                    if d != st["contiguous"]:
                        set_attr(st, "contiguous", d)
                    continue

                if typ == "STREAM":
                    sid = fr["id"]
                    dir_count(sid, True)
                    ent = self.streams.get(sid)
                    if ent is None:
                        ent = create_stream(sid)
                    data = bytes.fromhex(fr["data_hex"])
                    end = fr["offset"] + len(data)
                    fin = fr["fin"]
                    if end > MAX_OFF:
                        raise ProtoError("FRAME_ENCODING_ERROR", fi)
                    fs = ent["final_size"]
                    if fs is not None and (end > fs or (fin and end != fs)):
                        raise ProtoError("FINAL_SIZE_ERROR", fi)
                    old_highest = ent["highest"]
                    if fin and end < old_highest:
                        raise ProtoError("FINAL_SIZE_ERROR", fi)
                    if end > max_stream_data:
                        raise ProtoError("FLOW_CONTROL_ERROR", fi)
                    new_highest = end if end > old_highest else old_highest
                    new_total = self.tot["v"] - old_highest + new_highest
                    if new_total > max_data:
                        raise ProtoError("FLOW_CONTROL_ERROR", fi)
                    if not ent["reset"]:
                        store_bytes(ent["bytes"], fr["offset"], data, fi)
                    if new_highest != old_highest:
                        set_attr(ent, "highest", new_highest)
                    if new_total != self.tot["v"]:
                        set_attr(self.tot, "v", new_total)
                    if fin:
                        set_attr(ent, "final_size", end)
                    if not ent["reset"]:
                        bmap = ent["bytes"]
                        d = ent["delivered"]
                        while d in bmap:
                            d += 1
                        if d != ent["delivered"]:
                            set_attr(ent, "delivered", d)
                    continue

                if typ == "RESET_STREAM":
                    sid = fr["id"]
                    dir_count(sid, True)
                    ent = self.streams.get(sid)
                    if ent is None:
                        ent = create_stream(sid)
                    size = fr["final_size"]
                    fs = ent["final_size"]
                    if fs is not None and size != fs:
                        raise ProtoError("FINAL_SIZE_ERROR", fi)
                    old_highest = ent["highest"]
                    if size < old_highest:
                        raise ProtoError("FINAL_SIZE_ERROR", fi)
                    if size > max_stream_data:
                        raise ProtoError("FLOW_CONTROL_ERROR", fi)
                    new_highest = size if size > old_highest else old_highest
                    new_total = self.tot["v"] - old_highest + new_highest
                    if new_total > max_data:
                        raise ProtoError("FLOW_CONTROL_ERROR", fi)
                    if new_highest != old_highest:
                        set_attr(ent, "highest", new_highest)
                    if new_total != self.tot["v"]:
                        set_attr(self.tot, "v", new_total)
                    set_attr(ent, "final_size", size)
                    set_attr(ent, "reset", True)
                    continue

                if typ == "STOP_SENDING":
                    sid = fr["id"]
                    if (sid & 3) != 0:
                        raise ProtoError("STREAM_STATE_ERROR", fi)
                    if (sid >> 2) + 1 > self.max_streams_bidi:
                        raise ProtoError("STREAM_LIMIT_ERROR", fi)
                    ent = self.streams.get(sid)
                    if ent is None:
                        ent = create_stream(sid)
                    set_attr(ent, "stopped", True)
                    continue

                # HANDSHAKE_DONE / UNKNOWN are rejected in preflight.
                raise ProtoError("PROTOCOL_VIOLATION", fi)

        except ProtoError as err:
            rollback()
            self.fail_packet(e, p, t, err.frame, err.code)
            return

        # No CLOSE and no error: commit the packet.
        pnset.add(pkt["pn"])
        self.last_activity = t
        self.add_result(e, p, "accepted", "OK", t, None)

    # -- output ----------------------------------------------------------

    def build_result(self):
        out_packets = sorted(self.results,
                             key=lambda r: (r["event"], r["packet"]))
        streams = []
        for sid in sorted(self.streams.keys()):
            ent = self.streams[sid]
            d = ent["delivered"]
            bmap = ent["bytes"]
            if d:
                hx = bytes(bmap[i] for i in range(d)).hex()
            else:
                hx = ""
            streams.append({
                "id": sid,
                "highest": ent["highest"],
                "final_size": ent["final_size"],
                "reset": ent["reset"],
                "stopped": ent["stopped"],
                "delivered_hex": hx,
            })
        crypto = []
        for lvl in ("I", "H", "A"):
            st = self.crypto[lvl]
            d = st["contiguous"]
            bmap = st["bytes"]
            if d:
                hx = bytes(bmap[i] for i in range(d)).hex()
            else:
                hx = ""
            crypto.append({
                "level": lvl,
                "highest": st["highest"],
                "contiguous_hex": hx,
            })
        if self.state == "open":
            conn = {
                "state": "open",
                "code": None,
                "at_ms": None,
                "source": None,
                "peer_code": None,
                "last_activity_ms": self.last_activity,
            }
        else:
            conn = {
                "state": self.state,
                "code": self.code,
                "at_ms": self.at_ms,
                "source": self.source,
                "peer_code": self.peer_code,
                "last_activity_ms": self.last_activity,
            }
        return {
            "id": None,  # filled in by caller
            "packets": out_packets,
            "connection": conn,
            "keys": {
                "I": self.keys["I"],
                "H": self.keys["H"],
                "Z": self.keys["Z"],
                "A": self.keys["A"],
            },
            "received_total": self.tot["v"],
            "streams": streams,
            "crypto": crypto,
        }


def _frame_allowed(typ, lvl, fr):
    if typ == "PADDING" or typ == "PING":
        return True
    if typ == "ACK" or typ == "CRYPTO":
        return lvl == "I" or lvl == "H" or lvl == "A"
    if typ == "STREAM" or typ == "RESET_STREAM" or typ == "STOP_SENDING":
        return lvl == "Z" or lvl == "A"
    if typ == "CLOSE":
        if fr["app"]:
            return lvl == "Z" or lvl == "A"
        return True
    if typ == "HANDSHAKE_DONE":
        return False
    return False


def main():
    raw = sys.stdin.buffer.read(MAX_REQUEST + 1)
    try:
        obj = _parse(raw)
        _validate_root(obj)
        results = []
        for tr in obj["traces"]:
            runner = TraceRunner(tr)
            res = runner.run(tr["events"])
            res["id"] = tr["id"]
            results.append(res)
        out = {"version": 1, "results": results}
    except InvalidInput:
        out = {"error": "INVALID_INPUT"}
    except (RecursionError, MemoryError, OverflowError):
        out = {"error": "INVALID_INPUT"}
    sys.stdout.write(json.dumps(out, separators=(",", ":")))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
